// Replays the replication conformance vectors (vectors/replication/*.trace,
// generated by orderer-rust's simulator) against Consensus.Node. Every effect
// and state line must match exactly.
//
//   ReplicationTest [vectors-dir]
package io.github.abhijitkrm.orderer;

import static io.github.abhijitkrm.orderer.T.check;

import io.github.abhijitkrm.orderer.Consensus.Disk;
import io.github.abhijitkrm.orderer.Consensus.Effect;
import io.github.abhijitkrm.orderer.Consensus.Entry;
import io.github.abhijitkrm.orderer.Consensus.Msg;
import io.github.abhijitkrm.orderer.Consensus.Node;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.HexFormat;
import java.util.List;
import java.util.stream.Stream;

public final class ReplicationTest {
    static Path VEC = Path.of("vectors");

    static String hexs(byte[] d) { return d.length == 0 ? "-" : HexFormat.of().formatHex(d); }
    static byte[] unhex(String s) { return s.equals("-") ? new byte[0] : HexFormat.of().parseHex(s); }
    static String fmtEntry(Entry e) { return e.term() + ":" + hexs(e.data()); }
    static String fmtEntries(List<Entry> es) {
        if (es.isEmpty()) return "-";
        List<String> p = new ArrayList<>();
        for (Entry e : es) p.add(fmtEntry(e));
        return String.join(",", p);
    }
    static List<Entry> parseEntries(String s) {
        List<Entry> v = new ArrayList<>();
        if (s.equals("-")) return v;
        for (String part : s.split(",")) {
            int c = part.indexOf(':');
            v.add(new Entry(Long.parseLong(part.substring(0, c)), unhex(part.substring(c + 1))));
        }
        return v;
    }
    static int b(boolean x) { return x ? 1 : 0; }

    static String fmtMsg(Msg m) {
        return switch (m.kind) {
            case VOTE -> "vote " + m.term + " " + m.lastIndex + " " + m.lastTerm + " " + b(m.pre);
            case VOTE_REPLY -> "votereply " + m.term + " " + b(m.granted) + " " + b(m.pre);
            case APPEND -> "append " + m.term + " " + m.prevIndex + " " + m.prevTerm + " " + m.commit + " " + fmtEntries(m.entries);
            case APPEND_REPLY -> "appendreply " + m.term + " " + b(m.success) + " " + m.index;
        };
    }

    static Msg parseMsg(String[] w, int at) {
        long[] n = new long[6];
        for (int i = 1; i < 5 && at + i < w.length; i++) n[i] = w[at + i].matches("-?\\d+") ? Long.parseLong(w[at + i]) : 0;
        return switch (w[at]) {
            case "vote" -> Msg.vote(n[1], n[2], n[3], n[4] == 1);
            case "votereply" -> Msg.voteReply(n[1], n[2] == 1, n[3] == 1);
            case "append" -> Msg.append(n[1], n[2], n[3], parseEntries(w[at + 5]), n[4]);
            case "appendreply" -> Msg.appendReply(n[1], n[2] == 1, n[3]);
            default -> throw new IllegalArgumentException("unknown message " + w[at]);
        };
    }

    static String fmtEffect(Effect e) {
        switch (e.kind) {
            case SEND: return "send " + e.to + " " + fmtMsg(e.msg);
            case PERSIST: {
                var p = e.persist;
                return "persist " + p.token + " " + p.term + " " + (p.votedFor == Consensus.NONE ? "-" : p.votedFor) + " " + p.from + " "
                    + (p.hasCompact ? p.compactIndex + ":" + p.compactTerm : "-") + " " + fmtEntries(p.entries);
            }
            case APPLY: return "apply " + e.index + " " + fmtEntry(e.entry);
            case NEED_SNAPSHOT: return "needsnap " + e.to + " " + e.index + " " + e.term;
            default: return "restore " + e.index + " " + e.term;
        }
    }

    static String fmtState(Node n) {
        return "state role=" + n.role().label + " term=" + n.term() + " leader=" + (n.leader() == Consensus.NONE ? "-" : n.leader())
            + " commit=" + n.commitIndex() + " applied=" + n.appliedIndex() + " base=" + n.base() + " last=" + n.lastIndex();
    }

    static String field(String line, String key) {
        for (String w : line.trim().split("\\s+")) if (w.startsWith(key + "=")) return w.substring(key.length() + 1);
        throw new IllegalArgumentException("missing " + key);
    }

    static Node parseNode(String line) {
        String[] ps = field(line, "peers").split(",");
        int[] peers = new int[ps.length];
        for (int i = 0; i < ps.length; i++) peers[i] = Integer.parseInt(ps[i]);
        var cfg = new Consensus.Config(Long.parseLong(field(line, "election")), Long.parseLong(field(line, "heartbeat")),
            Integer.parseInt(field(line, "batch")), field(line, "prevote").equals("1"));
        String[] d = field(line, "disk").split(":", 5);
        Disk disk = new Disk();
        disk.term = Long.parseLong(d[0]);
        disk.votedFor = d[1].equals("-") ? Consensus.NONE : Integer.parseInt(d[1]);
        disk.base = Long.parseLong(d[2]);
        disk.baseTerm = Long.parseLong(d[3]);
        disk.log = parseEntries(d[4]);
        return new Consensus.Node(Integer.parseInt(field(line, "id")), peers, cfg, Long.parseUnsignedLong(field(line, "seed")), disk);
    }

    /** Returns checked drain points; reports the first difference through check(). */
    static int replay(String name, String text) {
        Node node = null;
        List<String> expected = new ArrayList<>();
        int checked = 0, ln = 0;
        for (String line : T.lines(text)) {
            ln++;
            String[] w = line.trim().isEmpty() ? new String[0] : line.trim().split("\\s+");
            if (w.length == 0) continue;
            switch (w[0]) {
                case "node" -> node = parseNode(line);
                case "in" -> {
                    switch (w[1]) {
                        case "tick" -> node.tick();
                        case "step" -> node.step(Integer.parseInt(w[2]), parseMsg(w, 3));
                        case "propose" -> node.propose(unhex(w[2]));
                        case "replicate" -> node.replicate();
                        case "persisted" -> node.persisted(Long.parseLong(w[2]));
                        case "compact" -> node.compact(Long.parseLong(w[2]));
                        case "install" -> node.installSnapshot(Integer.parseInt(w[2]), Long.parseLong(w[3]), Long.parseLong(w[4]), Long.parseLong(w[5]));
                        default -> throw new IllegalArgumentException(name + ":" + ln + ": unknown input " + w[1]);
                    }
                }
                case "out", "state" -> {
                    expected.add(line);
                    if (w[0].equals("state")) {
                        List<String> got = new ArrayList<>();
                        for (Effect e : node.takeEffects()) got.add("out " + fmtEffect(e));
                        got.add(fmtState(node));
                        if (!got.equals(expected)) {
                            int i = 0;
                            while (i < got.size() && i < expected.size() && got.get(i).equals(expected.get(i))) i++;
                            check(false, name, ":", ln, ": output differs at item ", i, "\n  want: ",
                                i < expected.size() ? expected.get(i) : "<end>", "\n  got:  ", i < got.size() ? got.get(i) : "<end>");
                            return checked;
                        }
                        checked++;
                        expected.clear();
                    }
                }
                default -> throw new IllegalArgumentException(name + ":" + ln + ": unknown line kind " + w[0]);
            }
        }
        return checked;
    }

    public static void main(String[] args) {
        if (args.length > 0) VEC = Path.of(args[0]);
        T.runAll(new Object[][] {
            {"replication_conformance_vectors", (T.Body) () -> {
                List<Path> files = new ArrayList<>();
                try (Stream<Path> s = Files.list(VEC.resolve("replication"))) {
                    s.filter(p -> p.toString().endsWith(".trace")).sorted().forEach(files::add);
                } catch (IOException e) { throw new RuntimeException(e); }
                check(!files.isEmpty(), "no traces in ", VEC.resolve("replication"));
                int total = 0;
                for (Path f : files) {
                    int n = replay(f.getFileName().toString(), T.slurp(f));
                    check(n > 100, f, ": only ", n, " checked steps");
                    total += n;
                }
                System.out.println("  replayed " + files.size() + " traces, " + total + " drain points");
            }},
        });
    }
}
